import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, Color, Vector2 } from 'three/webgpu';
import { uv, length, sub, mix, color, vec2, mul, fract, step } from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<Object>} [textContent]
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {string} [meshUrl]
 * @property {Object} [intent]
 * @property {Object} [visualSpec]
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, Color } = ctx.THREE;

  // root container
  const root = new Group();
  root.name = 'RichEmptyStatePanel';

  // ---------- PANEL BACKGROUND ----------
  const panelW = 3.2;
  const panelH = 2.2;
  const panelGeom = new PlaneGeometry(panelW, panelH);
  const uvNode = uv();
  const center = vec2(0.5, 0.5);
  const dist = length(sub(uvNode, center));
  const gradNode = mix(color('#14141a'), color('#0b0b10'), dist);
  const panelMat = new MeshBasicNodeMaterial({
    color: gradNode,
    transparent: true,
    depthWrite: false,
  });
  const panelMesh = new Mesh(panelGeom, panelMat);
  panelMesh.name = 'PanelBackground';
  root.add(panelMesh);

  // ---------- BORDER ----------
  const borderThickness = 0.006;
  const borderColor = new Color('#26262f');
  const borderMat = new MeshBasicNodeMaterial({
    color: borderColor,
    transparent: true,
    opacity: 1,
    depthWrite: false,
  });
  const borderGeom = new PlaneGeometry(panelW + borderThickness * 2, panelH + borderThickness * 2);
  const borderMesh = new Mesh(borderGeom, borderMat);
  borderMesh.position.set(0, 0, 0.001);
  borderMesh.name = 'PanelBorder';
  root.add(borderMesh);

  // ---------- GRID ----------
  const gridPitch = 0.25;
  const gridColor = new Color('#e8ecf2');
  const gridOpacity = 0.06;
  const gridMat = new MeshBasicNodeMaterial({
    color: gridColor,
    transparent: true,
    opacity: gridOpacity,
    depthWrite: false,
  });
  const gridNode = step(fract(mul(uvNode, 1 / gridPitch)), 0.02);
  const gridColorNode = mix(color('#000000'), gridColor, gridNode);
  gridMat.colorNode = gridColorNode;
  const gridMesh = new Mesh(panelGeom, gridMat);
  gridMesh.position.set(0, 0, 0.002);
  gridMesh.name = 'PanelGrid';
  root.add(gridMesh);

  // ---------- GHOST PREVIEW ----------
  const ghostGroup = new Group();
  ghostGroup.name = 'GhostPreview';
  ghostGroup.position.set(-panelW * 0.25, 0, 0.01);
  // outline
  const outlineGeom = new PlaneGeometry(1.1, 1.4);
  const outlineMat = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.3,
    wireframe: true,
    depthWrite: false,
  });
  const outlineMesh = new Mesh(outlineGeom, outlineMat);
  ghostGroup.add(outlineMesh);
  // dial circle
  const dialGeom = new PlaneGeometry(0.55, 0.55);
  const dialMat = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.22,
    depthWrite: false,
  });
  const dialMesh = new Mesh(dialGeom, dialMat);
  dialMesh.position.set(0, 0.2, 0);
  ghostGroup.add(dialMesh);
  // text bars
  const barGeom = new PlaneGeometry(0.7, 0.06);
  const barMat = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.22,
    depthWrite: false,
  });
  const bar1 = new Mesh(barGeom, barMat);
  const bar2 = new Mesh(barGeom, barMat);
  bar1.position.set(0, -0.2, 0);
  bar2.position.set(0, -0.3, 0);
  ghostGroup.add(bar1);
  ghostGroup.add(bar2);
  root.add(ghostGroup);

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'TextColumn';
  textGroup.position.set(panelW * 0.15, 0, 0.01);
  const padding = 0.5; // 2x base unit (0.25*2)
  let cursorY = panelH / 2 - padding; // start from top edge

  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 13,
      color: '#e8ecf2',
      align: 'left',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    const lineHeight = item.typography?.lineHeight ?? 1.5;
    txt.position.set(0, cursorY - (opts.fontSize / 100) * lineHeight, 0);
    textGroup.add(txt);
    cursorY -= (opts.fontSize / 100) * lineHeight + 0.05; // baseline rhythm
  }
  root.add(textGroup);

  // ---------- CTA BUTTON ----------
  const ctaWidth = 1.5;
  const ctaHeight = 0.36;
  const ctaGeom = new PlaneGeometry(ctaWidth, ctaHeight);
  const ctaUv = uv();
  const ctaGrad = mix(color('#ff4450'), color('#c1121f'), ctaUv.y);
  const ctaMat = new MeshBasicNodeMaterial({
    color: ctaGrad,
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
    transparent: true,
    depthWrite: false,
  });
  const ctaMesh = new Mesh(ctaGeom, ctaMat);
  ctaMesh.position.set(0, -panelH / 2 + padding + ctaHeight / 2, 0.01);
  ctaMesh.name = 'CTAButton';
  root.add(ctaMesh);

  const ctaLabel = ctx.fontAtlas.createText('BROWSE THE COLLECTION', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'center',
  });
  ctaLabel.position.set(0, 0, 0.001);
  ctaMesh.add(ctaLabel);

  // ---------- ANIMATIONS ----------
  const timelines = [];

  // mount fade-up
  root.traverse((obj) => {
    if (obj.isMesh) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });
  const mountTL = gsap.timeline();
  mountTL.to(root.position, {
    y: `+=0.2`,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  mountTL.to(
    root,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  timelines.push(mountTL);

  // ghost breathing
  const ghostTL = gsap.timeline({ repeat: -1, yoyo: true });
  ghostTL.to(
    ghostGroup,
    {
      opacity: 0.34,
      duration: 2.4,
      ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    },
    0
  );
  ghostTL.to(
    ghostGroup,
    {
      opacity: 0.24,
      duration: 2.4,
      ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    },
    2.4
  );
  timelines.push(ghostTL);

  // CTA press scale (placeholder for future interaction)
  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(ctaMesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' });
  timelines.push(pressTL);

  // ---------- HANDLERS ----------
  root.userData.handlers = {
    // placeholder for future interaction events
    press: () => pressTL.play(),
    release: () => pressTL.reverse(),
  };

  // ---------- PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const p = ctx.primitives[prim.name](root, prim.params);
      if (p?.cleanup) {
        timelines.push({ cleanup: p.cleanup });
      }
    }
  }

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => {
      if (t.kill) t.kill();
      if (t.cleanup) t.cleanup();
    });
    root.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
  };

  return root;
}
